import("./src/booking-conflicts.js").then(({ findConflicts }) => {
  const assert = require("node:assert/strict");
  const T = "2026-03-01T";
  const b = (id, room, s, e) => ({ id, room, start: T + s + "Z", end: T + e + "Z" });

  // R1: Feb 30 is not a real moment -> TypeError
  assert.throws(() => findConflicts([{ id: "a", room: "R", start: "2026-02-30T10:00:00Z", end: "2026-03-01T10:00:00Z" }]), TypeError);
  // R1: bad format -> TypeError
  assert.throws(() => findConflicts([{ id: "a", room: "R", start: "2026-03-01 10:00:00Z", end: "2026-03-01T11:00:00Z" }]), TypeError);
  assert.throws(() => findConflicts([{ id: "a", room: "R", start: "", end: "2026-03-01T11:00:00Z" }]), TypeError);
  assert.throws(() => findConflicts([{ id: "", room: "R", start: "2026-03-01T10:00:00Z", end: "2026-03-01T11:00:00Z" }]), TypeError);
  assert.throws(() => findConflicts("nope"), TypeError);
  // hour 24 is not real
  assert.throws(() => findConflicts([{ id: "a", room: "R", start: "2026-03-01T24:00:00Z", end: "2026-03-02T00:00:00Z" }]), TypeError);
  // R2: end == start -> RangeError
  assert.throws(() => findConflicts([b("a", "R", "10:00:00", "10:00:00")]), RangeError);
  // R2: end before start -> RangeError
  assert.throws(() => findConflicts([b("a", "R", "11:00:00", "10:00:00")]), RangeError);
  // R2: duplicate id -> TypeError
  assert.throws(() => findConflicts([b("a", "R1", "10:00:00", "11:00:00"), b("a", "R2", "12:00:00", "13:00:00")]), TypeError);
  // R3: first problem wins — booking[0] bad end (RangeError) even if booking[1] has dup/bad id
  assert.throws(() => findConflicts([b("a", "R", "11:00:00", "10:00:00"), { id: "a", room: "R", start: "2026-03-01T10:00:00Z", end: "2026-03-01T11:00:00Z" }]), RangeError);
  // R3: R1 of later booking beats R2 of same? no — per-booking order: R1 then R2. Bad end on booking[1], later booking[2] bad id: RangeError first.
  assert.throws(() => findConflicts([b("a", "R", "10:00:00", "11:00:00"), b("b", "R", "11:00:00", "10:00:00"), b("a", "R", "12:00:00", "13:00:00")]), RangeError);
  // R4: adjacency does not conflict
  assert.deepEqual(findConflicts([b("a", "R", "10:00:00", "11:00:00"), b("c", "R", "11:00:00", "12:00:00")]), []);
  // R4: identical ranges + containment; room case-sensitive
  assert.deepEqual(findConflicts([b("a", "R", "10:00:00", "12:00:00"), b("b", "R", "10:00:00", "12:00:00"), b("c", "R", "10:30:00", "11:00:00"), b("d", "r", "10:00:00", "12:00:00")]).sort(), [["a","b"],["a","c"],["b","c"]]);
  // R5: pair orientation and sorting
  assert.deepEqual(findConflicts([b("z", "R", "10:00:00", "12:00:00"), b("m", "R", "10:00:00", "12:00:00"), b("a", "R", "10:00:00", "12:00:00")]), [["a","m"],["a","z"],["m","z"]]);
  // R5: empty
  assert.deepEqual(findConflicts([]), []);
  // R6: no mutation
  const input = [b("a", "R", "10:00:00", "11:00:00"), b("b", "R", "10:30:00", "12:00:00")];
  const snapshot = JSON.stringify(input);
  const out = findConflicts(input);
  assert.equal(JSON.stringify(input), snapshot);
  assert.deepEqual(out, [["a","b"]]);
  console.log("all edge checks passed");
});
'
